from __future__ import annotations

import base64
import io
import json
import sys
import tarfile
import threading
import time
from dataclasses import replace
from pathlib import Path

PROJECT_ARCHIVE_B64 = ""


def _install_project() -> Path:
    project = Path("/kaggle/working/project")
    project.mkdir(parents=True, exist_ok=True)
    payload = base64.b64decode(PROJECT_ARCHIVE_B64, validate=True)
    with tarfile.open(fileobj=io.BytesIO(payload), mode="r:gz") as archive:
        archive.extractall(project, filter="data")
    return project


def _download_voc_data() -> Path:
    from scripts.download_data import download_voc2007

    data_dir = Path("/kaggle/working/data")
    print(json.dumps({"phase": "download_voc2007", "status": "started"}), flush=True)
    archives = download_voc2007(data_dir)
    print(
        json.dumps({"phase": "download_voc2007", "status": "completed", "archives": [str(path) for path in archives]}),
        flush=True,
    )
    return data_dir


def _start_heartbeat(phase: str) -> tuple[threading.Event, threading.Thread]:
    stop = threading.Event()
    started = time.perf_counter()

    def report() -> None:
        while not stop.wait(60):
            print(
                json.dumps({"phase": phase, "status": "running", "elapsed_seconds": round(time.perf_counter() - started)}),
                flush=True,
            )

    thread = threading.Thread(target=report, daemon=True)
    thread.start()
    return stop, thread


def main() -> None:
    project = _install_project()
    sys.path.insert(0, str(project))
    sys.path.insert(0, str(project / "src"))

    import torch

    from object_detector.config import load_config
    from object_detector.data.manifest import prepare_voc2007
    from object_detector.evaluation.evaluate import evaluate_checkpoint
    from object_detector.training.train import run_training

    if not torch.cuda.is_available():
        raise RuntimeError("Kaggle Kernel started without a CUDA GPU")
    capability = torch.cuda.get_device_capability(0)
    if capability[0] < 7:
        raise RuntimeError(
            f"allocated GPU capability sm_{capability[0]}{capability[1]} is unsupported by "
            f"PyTorch {torch.__version__}; request a T4 or newer GPU"
        )
    print(
        json.dumps(
            {
                "project": str(project),
                "object_detector_data_import": "ok",
                "cuda_device": torch.cuda.get_device_name(0),
                "cuda_capability": capability,
            }
        ),
        flush=True,
    )

    data_dir = _download_voc_data()
    manifest_dir = Path("/kaggle/working/manifests")
    output_dir = Path("/kaggle/working/artifacts")
    evaluation_dir = output_dir / "reference-fasterrcnn" / "evaluation"
    config = load_config(project / "configs" / "reference_fasterrcnn.yaml")
    config = replace(
        config,
        data=replace(config.data, data_dir=data_dir, manifest_dir=manifest_dir, num_workers=2),
        train=replace(config.train, amp=True),
        device="cuda",
        output_dir=output_dir,
    )

    metadata = prepare_voc2007(data_dir, manifest_dir)
    started = time.perf_counter()
    training_stop, training_thread = _start_heartbeat("training")
    try:
        result = run_training(config)
    finally:
        training_stop.set()
        training_thread.join()
    training_seconds = time.perf_counter() - started

    evaluation_started = time.perf_counter()
    evaluation_stop, evaluation_thread = _start_heartbeat("evaluation")
    try:
        evaluation = evaluate_checkpoint(
            result.run_dir / "best.pt",
            split="test",
            output_dir=evaluation_dir,
            device="cuda",
            score_threshold=config.evaluation.score_threshold,
            overwrite=True,
        )
    finally:
        evaluation_stop.set()
        evaluation_thread.join()
    evaluation_seconds = time.perf_counter() - evaluation_started

    summary = {
        "dataset_identity": metadata.identity,
        "split_counts": metadata.split_counts,
        "training_seconds": round(training_seconds, 3),
        "evaluation_seconds": round(evaluation_seconds, 3),
        "completed_epochs": result.completed_epochs,
        "metrics": evaluation.metrics,
        "checkpoint": str(result.run_dir / "best.pt"),
        "evaluation_dir": str(evaluation.output_dir),
    }
    (output_dir / "kaggle-run-summary.json").write_text(json.dumps(summary, indent=2, default=str) + "\n")
    print(json.dumps(summary, indent=2, default=str))


if __name__ == "__main__":
    main()
